function queryAI(userQuery, userData) {
  // 1. Create query hash
  const queryHash = hashFunction(userQuery + JSON.stringify(userData));

  // 2. Check cache layers
  let cachedResult = sessionStorage.getItem(queryHash);
  if (!cachedResult) {
    cachedResult = localStorage.getItem(queryHash);
  }
  if (!cachedResult) {
    cachedResult = await checkSupabaseCache(queryHash);
  }

  // 3. If found in cache, return (with cache_hit metric)
  if (cachedResult) {
    trackMetric('cache_hit', {queryHash, source: 'cache'});
    return JSON.parse(cachedResult);
  }

  // 4. If not in cache, make new API call
  const result = await openaiProxy(userQuery, userData);

  // 5. Store in all cache layers
  sessionStorage.setItem(queryHash, JSON.stringify(result));
  localStorage.setItem(queryHash, JSON.stringify(result));
  await storeInSupabaseCache(queryHash, result);

  // 6. Track API call (not cached)
  trackMetric('api_call_new', {queryHash, cost, time});

  return result;
}
